KG42.register("clusters-48c3772babab8511c0621993",{"id":"14-stackelberg_pv_sharing::v142-d-CL002","paper":"14-stackelberg_pv_sharing","label":"Equal participation and period-specific role determination for PV prosumers","record":{"cluster_id":"v142-d-CL002","label":"Equal participation and period-specific role determination for PV prosumers","market_meaning":"PV prosumers participating in the microgrid have equal participation status and may assume supplier or demander roles according to electricity generation and consumption in each period; non-positive net energy corresponds to the buyer role.","mechanism_ids":["v141-a-M01"],"market_types":["LEM"],"process_stages":["participation"],"scope_disposition":"compatible","scope_explanation":"Both chains concern PV prosumers in M01. Role changes across periods are understood separately from the role-preservation conditions for price responses within a given period; equal participation is not interpreted as equal payoffs, nor is it extended to eligibility for all non-PV consumers.","assembly_status":"assembled","boundary_rationale":"Participation eligibility and role classification have independent market significance, and their conditions do not require optimal prices to be obtained first. General permission for bidirectional roles and the buyer condition are assembled as complementary elements, retaining single-node facts without creating new scientific edges between roles.","chain_bindings":[{"chain_id":"v141-c-R007","ownership":"primary","role":"core","rationale":"Specifies the scope of bidirectional participation and equal participation status of PV prosumers."},{"chain_id":"v141-c-R006","ownership":"primary","role":"core","rationale":"Supplements the general participation description with the net-energy condition for the buyer role in each period."}],"connections":[{"connection_id":"v142-d-CL002-L001","from_chain_id":"v141-c-R007","to_chain_id":"v141-c-R006","kind":"complementary_scope","from_refs":["v141-c-R007::phi::v141-c-R007-C001"],"to_refs":["v141-c-R006::phi::v141-c-R006-C001"],"evidence_ids":["v141-b-g01-e004","v141-b-g01-e005","v141-b-g01-e012"],"rationale":"General permission for supply and demand roles and classification as a buyer under non-positive net energy jointly define the mode of participation; the equal-participation provision is retained independently and is not treated as a causal premise for quantity calculations."}],"object_mappings":[],"gaps":[{"gap_id":"v142-d-CL002-G001","category":"unverified_source","description":"The participation and role evidence has still not undergone independent source checking; assembled indicates only that the candidate assembly is established within the stated scope of participation. The buyer classification is retained when net energy is zero, without thereby asserting that a positive trading quantity exists.","chain_ids":["v141-c-R006","v141-c-R007"],"object_refs":["v141-c-R006::phi::v141-c-R006-C001","v141-c-R007::phi::v141-c-R007-C001","v141-c-R007::phi::v141-c-R007-C002"],"evidence_ids":["v141-b-g01-e004","v141-b-g01-e005","v141-b-g01-e006","v141-b-g01-e012"],"proposal_ids":[],"required_work":"Manually check the participating entities, role conditions, and classification of zero net energy; do not treat candidate eligibility as an audited fact."}]},"rule_refs":["14-stackelberg_pv_sharing::v141-c-R007","14-stackelberg_pv_sharing::v141-c-R006"],"unresolved_rule_refs":[],"node_ids":["COMP-f66e9ec7493cbb66","KG31-1200d592ea9a790f"]});
